var productData=null;
function renderProducts(){if(!productData)return;var search=(document.getElementById("productSearch").value||"").toLowerCase();var cat=document.getElementById("productCat").value;var items=productData.items.filter(function(p){if(!p.price||p.price<=0)return false;if(search&&!p.name.toLowerCase().includes(search))return false;if(cat!=="all"&&p.category!==cat)return false;return true;});var maxSales=items.length>0?items[0].sales:1;var html="";items.slice(0,80).forEach(function(p,i){var w=Math.round(p.sales/maxSales*100);var rank=i+1;var medal=rank===1?"🥇":rank===2?"🥈":rank===3?"🥉":rank;var tag="";if(p.sales>1000)tag="🔥";else if(p.price<15&&p.sales>200)tag="💰";html+='<div style="display:grid;grid-template-columns:35px 1fr 90px 70px 80px;gap:0;padding:6px 8px;border-bottom:1px solid var(--border);align-items:center;'+(rank<=3?'background:var(--brand-light)':(p.price<15&&p.sales>200?'background:var(--yellow-light)':''))+'"><div style="text-align:center;font-weight:700;color:'+(rank<=3?'var(--brand)':'var(--text-dim)')+'">'+medal+'</div><div><span style="font-weight:600;color:var(--text);font-size:12px">'+tag+' '+p.name+'</span><span style="font-size:10px;color:var(--text-dim);margin-left:4px">'+p.spec+'</span><div style="height:2px;background:var(--border);border-radius:1px;margin-top:2px"><div style="height:2px;width:'+w+'%;background:'+(rank<=3?'var(--brand)':'#c8e6c9')+';border-radius:1px;min-width:2px"></div></div></div><div style="text-align:right;font-weight:700;font-size:12px;color:var(--text)">¥'+p.price+'</div><div style="text-align:right;font-weight:700;font-size:12px;color:var(--text)">'+p.sales+'</div><div style="text-align:center"><button class="btn btn-ghost" onclick="useProductForCopy(\''+p.name.replace(/'/g,"\\'")+'\','+p.price+')" style="font-size:10px;padding:2px 8px;white-space:nowrap">📝 写文案</button></div></div>'});document.getElementById("productsGrid").innerHTML=html||'<div style="text-align:center;padding:40px;color:var(--text-dim)">无匹配产品</div>';}

function renderProductRecs(){
  var el=document.getElementById("productRecs");
  if(!productData||!productData.items){el.innerHTML='<div style="padding:4px 0">暂无数据</div>';return;}
  var items=productData.items.filter(function(p){return p.price>0&&p.price<30&&p.sales>100;}).slice(0,4);
  if(!items.length){el.innerHTML='<div style="padding:4px 0">暂无推荐</div>';return;}
  var html="";
  items.forEach(function(p,i){
    var score=Math.round(p.sales/(p.price||1));
    var bg=i===0?"var(--brand-light)":"#fff";
    html+='<div style="background:'+bg+';border-radius:8px;padding:10px;margin-bottom:8px;border:1px solid var(--border)">'+
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:2px">'+
      '<span style="font-weight:700;font-size:12px;color:var(--text)">'+p.name+'</span>'+
      '<span style="font-size:10px;color:var(--brand);font-weight:600">'+(i===0?"⭐最佳":i===1?"🔥热门":i===2?"📈推荐":"💡可选")+'</span>'+
      '</div>'+
      '<div style="font-size:10px;color:var(--text-dim)">'+p.spec+' · ¥'+p.price+' · 销'+p.sales+'份 · 性价比'+score+'</div>'+
      '</div>';
  });
  el.innerHTML=html;
}

function useProductForCopy(name,price){
  document.querySelectorAll('.nav-item').forEach(function(n){n.classList.remove('active')});
  document.querySelectorAll('.page').forEach(function(p){p.classList.remove('active')});
  document.querySelector('[data-page="copy"]').classList.add('active');
  document.getElementById('page-copy').classList.add('active');
  document.getElementById('pageTitle').textContent='✍️ 文案创作';
  copyProducts=[name];
  setCopyConfig('customPrice',price);
  initCopyPage();
  toast('📝 已选中: '+name);
}

function loadProducts(){var el=document.getElementById('productsGrid');
  try{var local=JSON.parse(localStorage.getItem('qg_products')||'null');}catch(e){local=null;}
  if(local&&local.items&&local.items.length>0){
    productData=local;updateProductUI(local);renderProducts();renderProductRecs();return;
  }
  fetch('product_library.json?v='+Date.now()).then(function(r){return r.json()}).then(function(d){
    productData=d;updateProductUI(d);renderProducts();renderProductRecs();
  }).catch(function(){el.innerHTML='<div style="text-align:center;padding:60px;color:var(--text-dim)"><div style="font-size:40px;margin-bottom:12px">📦</div>产品库建设中<br><span style="font-size:12px">拖拽订单表上传或等cron自动生成</span></div>';document.getElementById('productUpdateTime').textContent='';});}
function updateProductUI(d){
  document.getElementById('productMeta').textContent=d.total_products+'个SKU · 来源: '+(d.source||'上传文件');
  document.getElementById('productUpdateTime').textContent='最近更新: '+(d.updated||'').substring(0,16);
  var sel=document.getElementById('productCat');sel.innerHTML='<option value="all">全部分类</option>';
  (d.categories||[]).forEach(function(c){sel.innerHTML+='<option value="'+c+'">'+c+'</option>';});
}
function handleProductFile(e){
  e.preventDefault();e.stopPropagation();
  var file=(e.dataTransfer?e.dataTransfer.files[0]:null)||(e.target?e.target.files[0]:null);
  if(!file)return;
  var zone=document.getElementById('productDropZone');
  zone.style.background='var(--brand-light)';
  toast('📂 正在解析 '+file.name+'...');
  var reader=new FileReader();
  reader.onload=function(ev){
    try{
      var wb=XLSX.read(ev.target.result,{type:'array'});
      var sheet=wb.Sheets[wb.SheetNames[0]];
      var rows=XLSX.utils.sheet_to_json(sheet,{header:1,defval:''});
      if(rows.length<2){toast('⚠️ 表格为空');return;}
toast('📄 '+rows.length+'行, 解析中...');
      var header=rows[0];
      var colName=-1,colSpec=-1,colQty=-1,colPrice=-1;
      for(var i=0;i<header.length;i++){
        var h=String(header[i]||'');
        if(h.indexOf('商品名称')>=0)colName=i;
        if(h.indexOf('规格')>=0&&h.indexOf('编号')<0)colSpec=i;
        if(h.indexOf('份数')>=0||h.indexOf('数量')>=0)colQty=i;
        if(h.indexOf('售价')>=0||h.indexOf('单价')>=0)colPrice=i;
        else if(h.indexOf('实收')>=0)colPrice=i;
      }
      if(colPrice<0){for(var j=0;j<header.length;j++){var hj=String(header[j]||'');if(hj.indexOf('价')>=0&&hj.indexOf('退款')<0&&hj.indexOf('优惠')<0){colPrice=j;break;}}}
      if(colName<0){toast('⚠️ 未找到「商品名称」列');return;}
      var hasPrice=colPrice>=0;
      // Debug: show detected columns
      var colInfo='列'+header.length+' | 商品名:'+(colName>=0?'第'+(colName+1)+'列':'未找到')+' | 价格:'+(hasPrice?'第'+(colPrice+1)+'列':'未识别')+' | 份数:'+(colQty>=0?'第'+(colQty+1)+'列':'未识别');
      console.log(colInfo);
      toast('📊 '+colInfo);
      var agg={};
      for(var r=1;r<rows.length;r++){
        var name=String(rows[r][colName]||'').trim();
        if(!name)continue;
        var spec=colSpec>=0?String(rows[r][colSpec]||'').trim():'';
        if(spec==='.'||spec==='')spec=''; // Treat "." as empty
        var qty=parseFloat(rows[r][colQty])||0;
        var price=parseFloat(rows[r][colPrice])||0;
        var key=name; // Only group by name, not spec
        if(!agg[key])agg[key]={name:name,spec:spec||'',sales:0,price:999};
        agg[key].sales+=qty;
        // Keep the most common price (lowest non-zero)
        if(price>0&&price<agg[key].price)agg[key].price=price;
        if(agg[key].spec===''&&spec!=='')agg[key].spec=spec;
      }
      var cats=[
        ['🔥 引流爆品',['一斤西瓜','引流','9.9','8.8']],
        ['🎯 当家爆款',['乐享桶','霸气西瓜桶','当家']],
        ['🆕 网红创新',['乌梅','干噎酸奶','酸奶捞','酸嘢','海盐青柠','网红','阳光玫瑰夹乌梅']],
        ['💎 高客单',['榴莲','商务五拼','豪华','蓝莓','整果']],
        ['🥗 拼盘套餐',['三拼','四拼','双拼','mini拼','组合','自选','套餐','大四拼','大三拼']],
        ['📦 经典果切',['果切','半个西瓜','西瓜汁','冰镇']]
      ];
      function autoCat(name,price){
        for(var i=0;i<cats.length;i++){for(var j=0;j<cats[i][1].length;j++){if(name.indexOf(cats[i][1][j])>=0)return cats[i][0];}}
        return price>=20?'💎 高客单':'📦 经典果切';
      }
      var items=[],catSet={};
      for(var k in agg){
        var a=agg[k];
        var cat=autoCat(a.name,a.price);
        catSet[cat]=true;
        if(a.price>0)items.push({name:a.name,spec:a.spec,price:Math.round(a.price*10)/10,sales:Math.round(a.sales),orders:Math.round(a.sales),category:cat});
      }
      items.sort(function(a,b){return b.sales-a.sales;});
      var data={updated:new Date().toISOString(),source:file.name,total_products:items.length,categories:Object.keys(catSet),items:items};
      localStorage.setItem('qg_products',JSON.stringify(data));
      productData=data;
      allProductsData=data.items||[];
      updateProductUI(data);
      renderProducts();
      renderCopyProductSelector();
      allProductsData=items;
      var priceSamples=items.slice(0,3).map(function(p){return '¥'+p.price}).join(',');
toast('✅ '+items.length+'个产品 | '+priceSamples);
    }catch(err){
      toast('⚠️ 解析失败: '+err.message);
    }
  };
  reader.readAsArrayBuffer(file);
}

