// ═══════ CLOUD SYNC · GitHub API（2026-09-19 新增）═══════
// 只同步 3 个 key；不删数据，只按时间戳合并（新者胜）
var CLOUD_REPO='sophiasolo/qieguo-now-workspace';
var CLOUD_PATH='sync/personal_data.json';
var CLOUD_KEYS=[{k:'qg_schedule_overrides',n:'社群运营排期'},{k:'qg_custom_cards',n:'自定义花字'},{k:'qg_deleted_cards',n:'已删花字'},{k:'qg_prompt_favs',n:'配图Prompt收藏'},{k:'qg_prompt_recipes',n:'Prompt配方'}];
var CLOUD_POLL_MS=2500;
var CLOUD_PULL_MS=5*60*1000;
var cloudState=null, cloudDirty=false, cloudBusy=false, cloudWatch=null, cloudPushTimer=null;
var cloudStatus='noconfig', cloudDetail='', cloudLastSync=0;

function cloudToken(){return localStorage.getItem('qg_ghtoken')||'';}
function cloudLoadState(){try{cloudState=JSON.parse(localStorage.getItem('qg_cloud_state')||'null');}catch(e){cloudState=null;}}
function cloudSaveState(){try{localStorage.setItem('qg_cloud_state',JSON.stringify(cloudState||{}));}catch(e){}}
function cloudSnapshot(){var o={};CLOUD_KEYS.forEach(function(x){o[x.k]=localStorage.getItem(x.k);});return o;}
function cloudHasLocal(){var c=cloudSnapshot();for(var i=0;i<CLOUD_KEYS.length;i++){if(c[CLOUD_KEYS[i].k]!==null)return true;}return false;}
function cloudEnc(str){var u=new TextEncoder().encode(str),b='';for(var i=0;i<u.length;i++)b+=String.fromCharCode(u[i]);return btoa(b);}
function cloudDec(b64){var s=atob(String(b64).replace(/[^A-Za-z0-9+/=]/g,'')),u=new Uint8Array(s.length);for(var i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return new TextDecoder().decode(u);}
function cloudAgo(t){if(!t)return '从未';var d=Math.floor((Date.now()-t)/1000);if(d<10)return '刚刚';if(d<60)return d+' 秒前';if(d<3600)return Math.floor(d/60)+' 分钟前';if(d<86400)return Math.floor(d/3600)+' 小时前';return Math.floor(d/86400)+' 天前';}
function cloudDevice(){var d=localStorage.getItem('qg_device_name');if(!d){d=((navigator.platform||'Device')+'·'+Math.random().toString(36).slice(2,6));try{localStorage.setItem('qg_device_name',d);}catch(e){}}return d;}
function cloudFirst(){return !localStorage.getItem('qg_cloud_first_done');}
function cloudMarkFirst(){try{localStorage.setItem('qg_cloud_first_done','1');}catch(e){}}

function cloudApi(method,body){
  var url='https://api.github.com/repos/'+CLOUD_REPO+'/contents/'+CLOUD_PATH;
  var opt={method:method,cache:'no-store',headers:{'Authorization':'Bearer '+cloudToken(),'Accept':'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'}};
  if(body){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(body);}
  return fetch(url+(method==='GET'?'?ref=main':''),opt);
}
function cloudErr(e){
  var m=String((e&&e.message)||e||'');
  if(m.indexOf('TOKEN')>=0)return 'Token 无效或权限不足 → 请重新生成 Token 并保存';
  if(m.indexOf('Failed to fetch')>=0||m.indexOf('NetworkError')>=0)return '网络请求被拦截或断网（检查是否装了什么拦截扩展）';
  return m;
}
function cloudSetStatus(s,d){cloudStatus=s;cloudDetail=d||'';cloudRenderPanel();cloudDot();}

function cloudEnsure(seedNow){
  if(!cloudState)cloudState={};
  var cur=cloudSnapshot();
  CLOUD_KEYS.forEach(function(x){
    if(!cloudState[x.k])cloudState[x.k]={t:(seedNow&&cur[x.k]!==null)?Date.now():0,v:cur[x.k]};
  });
}
function cloudApply(k,v){
  try{
    if(v===null||v===undefined)return;         // 永不由云端删除本机数据
    if(localStorage.getItem(k)!==v)localStorage.setItem(k,v);
  }catch(e){}
}
function cloudMergeRemote(remote,force){
  if(!remote||!remote.keys)return false;
  var applied=false,cur=cloudSnapshot();
  var primary=schedAmPrimary();
  CLOUD_KEYS.forEach(function(x){
    var r=remote.keys[x.k];if(!r)return;
    if(r.v===null||r.v===undefined)return;      // 云端空值不覆盖本机
    // 新加入同步的键：本机有数据、云端也有、而本机从无该键的同步历史 -> 按内容并集，谁都不丢
    var noHist=!cloudState[x.k]||!(cloudState[x.k].t>0);
    if(CLOUD_UNION_KEYS.indexOf(x.k)>=0&&noHist&&cur[x.k]!==null&&cur[x.k]!==undefined){
      var merged=cloudUnionValue(x.k,cur[x.k],r.v);
      if(merged!==null){
        if(merged!==cur[x.k]){
          cloudBackupNow();                        // 覆盖前自动备份，面板可一键还原
          cloudApply(x.k,merged);
          applied=true;
        }
        cloudState[x.k]={t:Date.now(),v:merged};
        if(merged!==r.v)cloudDirty=true;           // 本机独有的条目需要回传
        return;
      }
    }
    // ④ 排期只由叶子合并维护：整块快照覆盖会把「已删除 / 被本机否决」的内容整块盖回来，一律跳过
    if(x.k===SCHED_KEY)return;
    if(!cloudState[x.k])cloudState[x.k]={t:0,v:cur[x.k]};
    var st=cloudState[x.k];
    if(force||(r.t||0)>(st.t||0)){
      cloudApply(x.k,r.v);
      cloudState[x.k]={t:r.t||0,v:r.v};
      applied=true;
    }
  });
  if(remote.schedule){
    var m=schedMergeRemote(schedState(),remote.schedule,primary,Date.now());
    cloudState.schedule=m.state;
    var rc=normClaim(remote.schedule.primary),rv0=schedRevokeIntent();
    // 本机撤销意图比云端声明新 -> 保持撤销；否则采纳云端声明（含 id='' 的撤销声明）
    cloudState.schedPrimary=(rv0>0&&(!rc||rv0>=(rc.t||0)))?{id:'',t:rv0}:rc;
    if(m.applied){schedRebuildLocal();applied=true;}
  }else{
    // 第二台还是旧版（只推整块快照）：把当前本机排期展开成叶子，不丢数据
    var d0=schedDiffLocal(schedState(),schedOv(),Date.now(),schedDefVal);
    if(d0.changed)cloudState.schedule=d0.state;
    if(primary)cloudState.schedPrimary=cloudDevice();
  }
  return applied;
}
// ═══ SCHED MERGE PURE (纯函数，默认值由 defVal 回调提供；可被 node 单测抽取) ═══
var SCHED_FIELDS=['小程序','市场','品宣','朋友圈','节日','备注'];

function schedNorm(o){var r={};Object.keys(o||{}).sort().forEach(function(k){r[k]=o[k];});return r;}

// 主设备声明：{id:'设备标识', t:认领时间戳}；兼容早期只存设备名字符串的写法
function normClaim(c){
  if(!c)return null;
  if(typeof c==='string')return c?{id:c,t:0}:null;
  if(typeof c!=='object')return null;
  var id=(c.id===null||c.id===undefined)?'':String(c.id),ct=Number(c.t)||0;
  if(!id&&!ct)return null;
  return {id:id,t:ct};                         // id='' + t>0 = 撤销声明（与认领一起按时间戳仲裁）
}
function schedWinner(my,remote){
  var a=normClaim(my),b=normClaim(remote);
  if(!a)return b;
  if(!b)return a;
  return (a.t>=b.t)?a:b;
}

// 状态 = {leaves:{'日期|字段':{t,v}}, tomb:{'日期|字段':t}}
function schedCopyState(state){
  var st={leaves:{},tomb:{}},src=state||{};
  Object.keys(src.leaves||{}).forEach(function(k){
    var c=src.leaves[k]||{};
    if(c.v===null||c.v===undefined)return;
    st.leaves[k]={t:c.t||0,v:c.v};
  });
  Object.keys(src.tomb||{}).forEach(function(k){st.tomb[k]=src.tomb[k]||0;});
  return st;
}

// 本机展示态 + 默认排期 -> 叶子状态（只保留「与默认不同」的字段）
function schedDiffLocal(state,ov,now,defVal){
  var st=schedCopyState(state),changed=false,want={};
  Object.keys(ov||{}).forEach(function(d){
    var o=ov[d]||{};
    SCHED_FIELDS.forEach(function(f){
      var v=(o[f]===null||o[f]===undefined)?'':String(o[f]);
      var dv=String(defVal?defVal(d,f):'');
      if(v!==dv)want[d+'|'+f]=v;
    });
  });
  Object.keys(want).forEach(function(k){
    var v=want[k],cur=st.leaves[k];
    if(!cur||cur.v!==v){st.leaves[k]={t:now,v:v};changed=true;}
    // ② 只有「本机叶子比墓碑新」= 删除后又真的重填过，才清墓碑；否则保留，防云端旧值借重建再复活
    if(st.tomb[k]&&st.leaves[k]&&(st.leaves[k].t||0)>(st.tomb[k]||0)){delete st.tomb[k];changed=true;}
  });
  Object.keys(st.leaves).forEach(function(k){
    if(!Object.prototype.hasOwnProperty.call(want,k)){delete st.leaves[k];st.tomb[k]=now;changed=true;}
  });
  return {state:st,changed:changed};
}

// 叶子状态 -> 完整展示态（只有含叶子的日期才写 override；其余字段补默认值，避免吃掉默认排期）
function schedBuildOv(state,defVal){
  var ov={},by={};
  Object.keys((state&&state.leaves)||{}).forEach(function(k){
    var i=k.indexOf('|');if(i<0)return;
    var d=k.slice(0,i),f=k.slice(i+1);
    if(!by[d])by[d]={};
    by[d][f]=state.leaves[k].v;
  });
  Object.keys(by).forEach(function(d){
    var e={};
    SCHED_FIELDS.forEach(function(f){
      e[f]=Object.prototype.hasOwnProperty.call(by[d],f)?by[d][f]:String(defVal?defVal(d,f):'');
    });
    ov[d]=e;
  });
  return ov;
}

// 远端 -> 本机（逐条比时间戳；主设备对本机已有叶子 / 删除行使否决权）
function schedMergeRemote(state,remote,isPrimary,now){
  var st=schedCopyState(state),applied=false;
  var rl=(remote&&remote.leaves)||{},rt=(remote&&remote.tomb)||{};
  if(!Object.keys(rl).length&&!Object.keys(rt).length)return {state:st,applied:false,hasRemote:false};
  Object.keys(rl).forEach(function(k){
    var r=rl[k]||{},cur=st.leaves[k],tb=st.tomb[k]||0;
    if(r.v===null||r.v===undefined)return;
    // ① 本机墓碑不旧于云端叶子 -> 用户确实删过这条，拒绝复活（否则上传前那次 GET 就会把删掉的内容盖回来）
    if(tb&&tb>=(r.t||0))return;
    if(!(isPrimary&&cur)&&(!cur||(r.t||0)>(cur.t||0))){st.leaves[k]={t:r.t||0,v:r.v};applied=true;}
    if(st.tomb[k]&&(r.t||0)>(st.tomb[k]||0)){delete st.tomb[k];applied=true;}
  });
  Object.keys(rt).forEach(function(k){
    var t=rt[k]||0,cur=st.leaves[k];
    if(isPrimary&&cur)return;
    if(!cur||t>(cur.t||0)){
      if(cur){delete st.leaves[k];applied=true;}
      if(!st.tomb[k]||t>st.tomb[k])st.tomb[k]=t;
    }
  });
  return {state:st,applied:applied,hasRemote:true};
}
// ═══ /SCHED MERGE PURE ═══

// ═══ CLOUD UNION PURE (新键首次采纳时按内容并集合并；纯函数，可被 node 单测抽取) ═══
var CLOUD_UNION_KEYS=['qg_prompt_favs','qg_prompt_recipes'];

// 按 keyName（如 text）去重；同一条取 time 较新的；结果按 time 倒序
function cloudArrUnion(a,b,keyName){
  var out=[],seen={};
  function take(list){
    (list||[]).forEach(function(it){
      if(!it||typeof it!=='object')return;
      var k=String(it[keyName]===null||it[keyName]===undefined?'':it[keyName])+'||'+String(it.type||'');
      var cur=seen[k];
      if(!cur){seen[k]=it;out.push(it);return;}
      if(String(it.time||'')>String(cur.time||'')){
        seen[k]=it;
        var i=out.indexOf(cur);
        if(i>=0)out[i]=it;
      }
    });
  }
  take(a);take(b);
  out.sort(function(x,y){return String(y.time||'').localeCompare(String(x.time||''));});
  return out;
}

// 两个 JSON 字符串的并集；无法解析时返回 null（调用方退化为按时间戳处理）
function cloudUnionValue(k,localStr,remoteStr){
  try{
    if(localStr===null||localStr===undefined)return remoteStr;
    if(remoteStr===null||remoteStr===undefined)return localStr;
    if(localStr===remoteStr)return localStr;
    if(k==='qg_prompt_favs'){
      return JSON.stringify(cloudArrUnion(JSON.parse(localStr||'[]'),JSON.parse(remoteStr||'[]'),'text'));
    }
    if(k==='qg_prompt_recipes'){
      var L=JSON.parse(localStr||'{}')||{},R=JSON.parse(remoteStr||'{}')||{},out={};
      Object.keys(L).concat(Object.keys(R)).forEach(function(t){
        if(Object.prototype.hasOwnProperty.call(out,t))return;
        out[t]=cloudArrUnion(L[t],R[t],'text');
      });
      return JSON.stringify(out);
    }
  }catch(e){}
  return null;
}
// ═══ /CLOUD UNION PURE ═══

var SCHED_KEY='qg_schedule_overrides';
function schedOv(){try{return JSON.parse(localStorage.getItem(SCHED_KEY)||'{}')||{};}catch(e){return {};}}
function schedState(){
  if(!cloudState)cloudState={};
  if(!cloudState.schedule)cloudState.schedule={leaves:{},tomb:{}};
  var x=cloudState.schedule;
  if(!x.leaves)x.leaves={};
  if(!x.tomb)x.tomb={};
  return x;
}
// 该日期的默认排期（与渲染同源：SCHEDULE_DATA，键 'YYYY-MM' / 日 'DD'）
function schedDefEntry(d){
  var e={},key=String(d||'').substring(0,7),dd=String(d||'').substring(8);
  SCHED_FIELDS.forEach(function(f){e[f]='';});
  try{
    var data=SCHEDULE_DATA&&SCHEDULE_DATA[key];
    var day=(data&&data.days)?data.days[dd]:null;
    if(day)SCHED_FIELDS.forEach(function(f){if(day[f])e[f]=String(day[f]);});
  }catch(err){}
  return e;
}
function schedDefVal(d,f){return schedDefEntry(d)[f]||'';}
function schedIsPrimary(){try{return localStorage.getItem('qg_cloud_primary')==='1';}catch(e){return false;}}
function schedMyClaim(){
  if(!schedIsPrimary())return null;
  var t=0;try{t=Number(localStorage.getItem('qg_cloud_primary_at'))||0;}catch(e){}
  return {id:cloudDevice(),t:t};
}
// 本机「撤销主设备」意图时间戳：点「取消本机主设备标记」写入，重新「设为主设备」清掉
function schedRevokeIntent(){try{return Number(localStorage.getItem('qg_cloud_primary_off'))||0;}catch(e){return 0;}}
// 有效主设备 = 本机声明 / 云端声明 / 本机撤销意图 三者中时间戳最新者；撤销胜出 = 无主设备（双向逐条合并）
function schedEffectivePrimary(){
  var remote=null;try{remote=cloudState?cloudState.schedPrimary:null;}catch(e){}
  var w=schedWinner(schedMyClaim(),remote),rv=schedRevokeIntent();
  if(rv>0&&(!w||rv>=(w.t||0)))return {id:'',t:rv};
  return w;
}
function schedAmPrimary(){
  var w=schedEffectivePrimary();
  return !!(w&&w.id===cloudDevice());
}
function schedWriteOv(ov){
  try{
    if(ov&&Object.keys(ov).length)localStorage.setItem(SCHED_KEY,JSON.stringify(ov));
    else localStorage.removeItem(SCHED_KEY);
  }catch(e){}
}
function schedSyncLocalWith(ts){
  var d=schedDiffLocal(schedState(),schedOv(),(ts===undefined?Date.now():ts),schedDefVal);
  if(d.changed){cloudState.schedule=d.state;try{cloudSaveState();}catch(e){}}
  return d.changed;
}
function schedSyncLocal(){return schedSyncLocalWith(Date.now());}
function schedRebuildLocal(){
  try{schedWriteOv(schedBuildOv(cloudState.schedule||{},schedDefVal));}catch(e){}
}
function schedTogglePrimary(){
  if(schedIsPrimary()){
    try{localStorage.removeItem('qg_cloud_primary');localStorage.removeItem('qg_cloud_primary_at');
        localStorage.setItem('qg_cloud_primary_off',String(Date.now()));}catch(e){}
    // 撤销必须带时间戳并发布到云端：否则推送前的 GET 会把云端旧声明读回来 -> 否决权复活
    cloudLoadState();if(!cloudState)cloudState={};
    cloudState.schedPrimary={id:'',t:schedRevokeIntent()};
    toast('已取消本机主设备标记（排期恢复逐条按时间合并）');
  }else{
    try{localStorage.setItem('qg_cloud_primary','1');localStorage.setItem('qg_cloud_primary_at',String(Date.now()));
        localStorage.removeItem('qg_cloud_primary_off');}catch(e){}
    toast('⭐ 本机已设为主设备：排期以本机为准');
  }
  try{cloudSaveState();}catch(e){}
  cloudRenderPanel();cloudDirty=true;cloudPush(false);
}
function cloudBackupNow(){
  try{
    var bk={};CLOUD_KEYS.forEach(function(x){bk[x.k]=localStorage.getItem(x.k);});
    localStorage.setItem('qg_cloud_backup',JSON.stringify({at:Date.now(),keys:bk}));
  }catch(e){}
}
function cloudKeysNorm(keys){
  var r={};
  Object.keys(keys||{}).forEach(function(k){if(k===SCHED_KEY)return;r[k]=keys[k];});
  return r;
}
// 「云端已与本机一致」判断（排期整块快照的键序会漂，故排除后单独比叶子），避免每次同步都产生空提交
function cloudSame(a,b){
  if(!a||!b)return false;
  var ka=cloudKeysNorm(a.keys),kb=cloudKeysNorm(b.keys),names={};
  Object.keys(ka).forEach(function(k){names[k]=1;});Object.keys(kb).forEach(function(k){names[k]=1;});
  var sameKeys=true;
  Object.keys(names).forEach(function(k){
    var x=ka[k]||{},y=kb[k]||{};
    if(CLOUD_UNION_KEYS.indexOf(k)>=0){ if(String(x.v)!==String(y.v))sameKeys=false; }
    else if(JSON.stringify(x)!==JSON.stringify(y))sameKeys=false;
  });
  if(!sameKeys)return false;
  var sa=a.schedule||{},sb=b.schedule||{};
  if(JSON.stringify(schedNorm(sa.leaves))!==JSON.stringify(schedNorm(sb.leaves)))return false;
  if(JSON.stringify(schedNorm(sa.tomb))!==JSON.stringify(schedNorm(sb.tomb)))return false;
  return JSON.stringify(normClaim(sa.primary))===JSON.stringify(normClaim(sb.primary));
}

function cloudPayload(){
  schedSyncLocal();                              // 上传前把本机排期刷成叶子
  var keys={},cur=cloudSnapshot(),st=schedState();
  CLOUD_KEYS.forEach(function(x){
    if(x.k===SCHED_KEY){                         // 排期：另出 v2 兼容整块快照（供旧版客户端读）
      var ov=schedBuildOv(st,schedDefVal),ks=Object.keys(ov);
      if(ks.length){
        var maxT=0;Object.keys(st.leaves).forEach(function(k){var t=st.leaves[k].t||0;if(t>maxT)maxT=t;});
        keys[x.k]={t:maxT,v:JSON.stringify(ov)};
      }
      return;
    }
    var v=(cloudState&&cloudState[x.k]&&cloudState[x.k].v!==undefined)?cloudState[x.k].v:cur[x.k];
    if(v===null||v===undefined)return;          // 空值不上传
    var t=(cloudState&&cloudState[x.k]&&cloudState[x.k].t)||Date.now();
    keys[x.k]={t:t,v:v};
  });
  return {v:3,updated:new Date().toISOString(),source:cloudDevice(),keys:keys,
          schedule:{leaves:st.leaves,tomb:st.tomb,primary:schedEffectivePrimary()}};
}
function cloudRerender(){
  try{renderSchedule();}catch(e){}
  try{loadCustomCards();renderCardLib();}catch(e){}
  try{renderPromptLib();}catch(e){}
  try{renderRecipeHistory();}catch(e){}
}
function cloudSchedulePush(){
  if(cloudPushTimer)clearTimeout(cloudPushTimer);
  cloudPushTimer=setTimeout(function(){cloudPush(false);},2000);
}
function cloudTick(){
  if(!cloudToken())return;
  cloudLoadState();
  if(!cloudState)cloudState={};
  var cur=cloudSnapshot(),changed=false;
  CLOUD_KEYS.forEach(function(x){
    if(x.k===SCHED_KEY)return;                   // 排期走逐条合并
    var st=cloudState[x.k];
    if(!st){cloudState[x.k]={t:0,v:cur[x.k]};return;}
    if(cur[x.k]!==st.v){cloudState[x.k]={t:Date.now(),v:cur[x.k]};changed=true;}
  });
  if(schedSyncLocal())changed=true;               // 本机排期逐条改动 -> 打时间戳
  if(JSON.stringify(normClaim(schedEffectivePrimary()))!==JSON.stringify(normClaim(cloudState.pubPrimary)))changed=true;   // 主设备声明尚未发布
  if(changed){cloudSaveState();cloudDirty=true;cloudSetStatus('dirty','检测到本机修改，2 秒后自动上传…');cloudSchedulePush();}
}
function cloudPush(manual,retry){
  if(cloudBusy)return;
  if(!cloudToken()){cloudSetStatus('noconfig','未配置 Token —— 粘贴后即可开始同步');if(manual)toast('请先保存 GitHub Token');return;}
  cloudBusy=true;
  schedSyncLocal();                              // 合并前先让本机编辑成为叶子
  if(manual)cloudSetStatus('syncing','正在上传…');
  cloudApi('GET').then(function(r){
    if(r.status===401||r.status===403)throw new Error('TOKEN');
    if(r.status===404)return {data:null,sha:null};
    if(!r.ok)throw new Error('HTTP '+r.status);
    return r.json().then(function(j){var d=null;try{d=JSON.parse(cloudDec(j.content));}catch(e){}return {data:d,sha:j.sha};});
  }).then(function(res){
    if(res.data)cloudMergeRemote(res.data,false);
    cloudEnsure(false);cloudSaveState();
    var payload=cloudPayload();
    cloudBusy=false;
    if(res.data&&cloudSame(res.data,payload)){
      cloudDirty=false;cloudLastSync=Date.now();try{localStorage.setItem('qg_cloud_last',String(cloudLastSync));}catch(e){}
      cloudState.pubPrimary=normClaim(payload.schedule.primary);cloudSaveState();
      cloudSetStatus('ok','云端已是最新 · '+cloudAgo(cloudLastSync));
      if(manual)toast('✅ 云端已是最新');
      return;
    }
    var body={message:'☁️ 同步个人数据 · '+new Date().toLocaleString('zh-CN'),content:cloudEnc(JSON.stringify(payload,null,2)),branch:'main'};
    if(res.sha)body.sha=res.sha;
    cloudBusy=true;
    cloudApi('PUT',body).then(function(r2){
      if(r2.status===409){
        cloudBusy=false;
        if(!retry){setTimeout(function(){cloudPush(manual,true);},1500);}
        else cloudSetStatus('error','两处同时修改冲突，请再点一次「立即上传」');
        return;
      }
      if(!r2.ok)return r2.text().then(function(t){throw new Error('HTTP '+r2.status+' '+String(t).slice(0,120));});
      cloudBusy=false;cloudDirty=false;cloudLastSync=Date.now();
      try{localStorage.setItem('qg_cloud_last',String(cloudLastSync));}catch(e){}
      cloudState.pubPrimary=normClaim(payload.schedule.primary);cloudSaveState();
      cloudMarkFirst();
      cloudSetStatus('ok','已同步到云端 · '+cloudAgo(cloudLastSync));
      if(manual)toast('✅ 已上传到云端');
      cloudRerender();
    }).catch(function(e){
      cloudBusy=false;cloudSetStatus('error','上传失败：'+cloudErr(e));
      if(manual)toast('⚠️ 上传失败');
    });
  }).catch(function(e){
    cloudBusy=false;cloudSetStatus('error',cloudErr(e));
    if(manual)toast('⚠️ 上传失败');
  });
}
function cloudPull(manual,cb){
  if(!cloudToken()){cloudSetStatus('noconfig','未配置 Token —— 粘贴后即可开始同步');if(cb)cb('noconfig');return;}
  if(cloudBusy){if(cb)cb('busy');return;}
  cloudBusy=true;
  if(manual)cloudSetStatus('syncing','正在拉取…');
  cloudApi('GET').then(function(r){
    if(r.status===401||r.status===403)throw new Error('TOKEN');
    if(r.status===404)return {data:null,sha:null};
    if(!r.ok)throw new Error('HTTP '+r.status);
    return r.json().then(function(j){var d=null;try{d=JSON.parse(cloudDec(j.content));}catch(e){}return {data:d,sha:j.sha};});
  }).then(function(res){
    cloudBusy=false;
    if(!res.data){
      cloudEnsure(true);
      CLOUD_KEYS.forEach(function(x){var v=localStorage.getItem(x.k);if(v!==null)cloudState[x.k]={t:Date.now(),v:v};});
      cloudSaveState();
      cloudMarkFirst();
      if(cloudHasLocal()){cloudDirty=true;cloudSetStatus('dirty','云端还没有数据，正在上传本机数据…');cloudPush(false);}
      else cloudSetStatus('ok','云端与本机都还没有数据');
      if(cb)cb(null,null);
      return;
    }
    cloudLoadState();
    var first=cloudFirst();
    if(first){
      var bk={};CLOUD_KEYS.forEach(function(x){bk[x.k]=localStorage.getItem(x.k);});
      try{localStorage.setItem('qg_cloud_backup',JSON.stringify({at:Date.now(),keys:bk}));}catch(e){}
      cloudState={};
    }
    // 本机叶子必须参与合并，否则会被云端内容整体覆盖（首次同步用 t=0：同名字段云端取胜，本机独有编辑保留）
    schedSyncLocalWith(first?0:undefined);
    cloudEnsure(false);
    var applied=cloudMergeRemote(res.data,first);
    cloudSaveState();
    cloudMarkFirst();
    var orphaned=false;
    CLOUD_KEYS.forEach(function(x){
      var r=(res.data.keys&&res.data.keys[x.k])?res.data.keys[x.k]:null;
      var v=localStorage.getItem(x.k);
      if(v!==null&&!r){cloudState[x.k]={t:Date.now(),v:v};orphaned=true;}
    });
    if(orphaned){cloudSaveState();cloudDirty=true;}
    cloudLastSync=Date.now();try{localStorage.setItem('qg_cloud_last',String(cloudLastSync));}catch(e){}
    cloudSetStatus('ok',(first?'已采用云端数据（本机原有数据已备份，可点「恢复本机旧数据」）':'已拉取云端数据')+' · '+cloudAgo(cloudLastSync));
    if(applied)cloudRerender();
    cloudTick();
    if(orphaned||cloudDirty)cloudPush(false);
    if(cb)cb(null,res);
  }).catch(function(e){
    cloudBusy=false;cloudSetStatus('error',cloudErr(e));
    if(cb)cb('err');
  });
}
function cloudPullNow(){cloudPull(true);}
function cloudStartWatch(){
  if(cloudWatch)clearInterval(cloudWatch);
  cloudWatch=setInterval(cloudTick,CLOUD_POLL_MS);
  setInterval(function(){if(cloudToken()&&!cloudDirty&&!cloudBusy)cloudPull(false);},CLOUD_PULL_MS);
  window.addEventListener('beforeunload',function(){cloudTick();});
  document.addEventListener('visibilitychange',function(){if(document.visibilityState==='hidden')cloudTick();});
}
function cloudInit(){
  cloudLastSync=parseInt(localStorage.getItem('qg_cloud_last')||'0',10)||0;
  cloudLoadState();
  if(!cloudToken()){cloudSetStatus('noconfig','未配置 Token —— 点这里粘贴后即可跨电脑同步');return;}
  cloudTick();
  cloudPull(false);
  cloudStartWatch();
}
function cloudDot(){
  var b=document.getElementById('cloudBtn');if(!b)return;
  var map={ok:'☁️ 云同步',syncing:'⏳ 同步中…',dirty:'📤 待上传',error:'⚠️ 同步异常',noconfig:'☁️ 云同步'};
  b.textContent=map[cloudStatus]||'☁️ 云同步';
  b.style.color=(cloudStatus==='error')?'var(--red)':'';
}
function openCloudModal(){cloudRenderPanel();document.getElementById('cloudModal').classList.add('show');}
function closeCloudModal(){document.getElementById('cloudModal').classList.remove('show');}
function cloudRenderPanel(){
  var box=document.getElementById('cloudStatusBox');if(!box)return;
  var color={ok:'var(--brand)',syncing:'var(--text-dim)',dirty:'#b26a00',error:'var(--red)',noconfig:'var(--text-dim)'}[cloudStatus]||'var(--text-dim)';
  var head={ok:'✅ 已连接',syncing:'⏳ 同步中…',dirty:'📤 本机有新修改，排队上传',error:'⚠️ 同步异常',noconfig:'⚪ 未配置 Token'}[cloudStatus]||'';
  var h='<div style="font-weight:700;color:'+color+';margin-bottom:6px">'+head+'</div>';
  if(cloudDetail)h+='<div style="margin-bottom:6px">'+cloudDetail+'</div>';
  h+='<div>🕒 上次成功同步：'+cloudAgo(cloudLastSync)+'</div>';
  var tk=cloudToken();
  h+='<div>🔑 Token：'+(tk?('已保存（仅显示前缀 '+tk.slice(0,11)+'⚪⚪⚪⚪）'):'未保存')+'</div>';
  CLOUD_KEYS.forEach(function(x){
    var s=(cloudState||{})[x.k]||{},v=localStorage.getItem(x.k);
    h+='<div style="color:var(--text-dim)">· '+x.n+'：'+(v?'有数据':'无数据')+(s.t?'（本机最后修改 '+cloudAgo(s.t)+'）':'')+'</div>';
  });
  var st=schedState();
  var leafN=Object.keys(st.leaves).length,tombN=Object.keys(st.tomb).length;
  h+='<div style="margin-top:8px;border-top:1px solid var(--border);padding-top:8px">📅 排期逐条合并：<b>'+leafN+'</b> 条（按日期+字段），已删日期 '+tombN+' 条</div>';
  var eff=schedEffectivePrimary(),me=cloudDevice();
  var effTxt=(eff&&eff.id&&eff.id===me)?'<b>本机</b>（排期以本机为准，其他电脑改同一日期会被本机覆盖）'
            :((eff&&eff.id)?('其他设备 '+eff.id+'（排期以它为准）'):'未设置（排期按时间戳逐条合并）');
  h+='<div>⭐ 主设备：'+effTxt+
     ' <button class="btn btn-ghost" style="font-size:10px;padding:1px 8px" onclick="schedTogglePrimary()">'+(schedIsPrimary()?'取消本机主设备标记':'设为主设备')+'</button></div>';
  box.innerHTML=h;
}
function cloudSaveToken(){
  var v=document.getElementById('cloudTokenInput').value.trim();
  if(!v){toast('请先粘贴 Token');return;}
  if(v.indexOf('github_pat_')!==0&&v.indexOf('ghp_')!==0){
    if(!confirm('这看起来不像 GitHub Token（通常以 github_pat_ 或 ghp_ 开头），仍要保存吗？'))return;
  }
  localStorage.setItem('qg_ghtoken',v);
  document.getElementById('cloudTokenInput').value='';
  toast('✅ Token 已保存到本机浏览器');
  cloudSetStatus('syncing','正在验证 Token 并同步…');
  cloudPull(true);
  cloudStartWatch();
}
function cloudClearToken(){
  if(!confirm('清除本机保存的 Token？清除后会停止云同步（云端数据不受影响）。'))return;
  localStorage.removeItem('qg_ghtoken');
  if(cloudWatch)clearInterval(cloudWatch);
  cloudSetStatus('noconfig','Token 已清除，云同步已停止');
}
function cloudRestoreBackup(){
  var raw=localStorage.getItem('qg_cloud_backup');
  if(!raw){toast('没有可恢复的本机旧数据');return;}
  var bk;try{bk=JSON.parse(raw);}catch(e){toast('备份文件损坏');return;}
  if(!confirm('用本机备份（'+new Date(bk.at).toLocaleString('zh-CN')+'）覆盖当前数据，并上传到云端？'))return;
  cloudLoadState();if(!cloudState)cloudState={};
  CLOUD_KEYS.forEach(function(x){
    if(bk.keys&&Object.prototype.hasOwnProperty.call(bk.keys,x.k)){
      var v=bk.keys[x.k];
      if(v===null){try{localStorage.removeItem(x.k);}catch(e){}}
      else{try{localStorage.setItem(x.k,v);}catch(e){}cloudState[x.k]={t:Date.now(),v:v};}
    }
  });
  schedSyncLocal();schedRebuildLocal();
  cloudSaveState();cloudRerender();cloudDirty=true;
  toast('已恢复本机旧数据，正在上传…');cloudPush(true);
}
function cloudExportBackup(){
  var data={exported_at:new Date().toISOString(),version:2};
  var n=0;
  CLOUD_KEYS.forEach(function(x){var v=localStorage.getItem(x.k);if(v!==null){data[x.k]=v;n++;}});
  var blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});
  var a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download='qg_personal_backup_'+new Date().toISOString().slice(0,10)+'.json';
  document.body.appendChild(a);a.click();document.body.removeChild(a);
  toast('💾 已导出备份文件（'+n+' 项）');
}

